import createClient from 'openapi-fetch';

import { env } from '@/config/env';

import { type AuthHandlers, createHttp } from './http';
import type { paths } from './schema';

// The only way the app reaches the API (docs/MOBILE_ARCHITECTURE.md#api): paths,
// parameters, bodies and responses are typed from the committed contract
// (openapi/openapi.json → schema.d.ts, regenerated by `pnpm contract`).
// Features call it from their api.ts through TanStack Query; screens never
// call it directly.

let authHandlers: AuthHandlers | undefined;

/** Registered by src/auth/session.ts: this layer knows nothing about sessions. */
export function setAuthHandlers(handlers: AuthHandlers): void {
  authHandlers = handlers;
}

const sessionAuth: AuthHandlers = {
  getAccessToken: () => authHandlers?.getAccessToken() ?? Promise.resolve(null),
  refreshAfterRejection: (rejected) =>
    authHandlers?.refreshAfterRejection(rejected) ?? Promise.resolve(null),
};

/** Authenticated endpoints: every call carries the session's access token. */
export const api = createClient<paths>({
  baseUrl: env.EXPO_PUBLIC_API_URL,
  fetch: createHttp({ auth: sessionAuth }),
});

/** Public endpoints (sign-in, refresh, logout): no token, no refresh. */
export const publicApi = createClient<paths>({
  baseUrl: env.EXPO_PUBLIC_API_URL,
  fetch: createHttp(),
});

export type { AuthHandlers } from './http';
export type { components, paths } from './schema';
